/**
 * The site's three families. Young Serif is display-only — empty states and onboarding, never
 * the chrome and never document content.
 */
export interface FontFamilies {
  /**
   * the chrome face; a rounded humanist that reads slightly wider than a typical UI font.
   *
   * CSS: `--font-sans` · type `fontFamily`
   */
  readonly sans: string;
  /**
   * display only.
   *
   * CSS: `--font-serif` · type `fontFamily`
   */
  readonly serif: string;
  /**
   * DESIGN_TOKENS.md §1 elides this stack after `Liberation Mono`; the elision is the standard
   * Tailwind v4 monospace stack, written out here in full.
   *
   * CSS: `--font-mono` · type `fontFamily`
   */
  readonly mono: string;
}

