/**
 * The document-surface palette. DESIGN_TOKENS.md §2.3: an editor has TWO palettes and
 * conflating them is the classic mistake. The page stays true white in both schemes — a
 * document is white paper, and a warm-tinted or dark page changes what the author sees relative
 * to what they will print or send. What changes with the scheme is the canvas backdrop behind
 * the page, the page shadow, and the in-canvas UI. A reading-mode inversion of the page itself
 * is a user setting, not a theme consequence. These are the tokens the Rust canvas needs and a
 * CSS custom property cannot reach it, which is the reason this pipeline emits three artefacts
 * instead of one.
 */
export interface DocumentSurfaces {
  readonly light: DocumentColors;
  readonly dark: DocumentColors;
}

export interface DocumentColors {
  /**
   * `color.paper` behind a true-white page makes the page read as a distinct, lit object rather
   * than dissolving into the background.
   *
   * CSS: `--document-light-backdrop` · type `color` · usage `fill-only`
   */
  readonly backdrop: string;
  /**
   * CSS: `--document-light-page` · type `color` · usage `fill-only`
   */
  readonly page: string;
  /**
   * CSS: `--document-light-page-border` · type `color` · usage `fill-only`
   */
  readonly pageBorder: string;
  /**
   * CSS: `--document-light-page-shadow` · type `shadow`
   */
  readonly pageShadow: string;
  /**
   * `color.green` at 18% alpha (0.18 × 255 = 46 = 0x2e).
   *
   * CSS: `--document-light-selection-fill` · type `color` · usage `fill-only`
   */
  readonly selectionFill: string;
  /**
   * CSS: `--document-light-selection-handle` · type `color` · usage `fill-only`
   */
  readonly selectionHandle: string;
  /**
   * CSS: `--document-light-alignment-guide` · type `color` · usage `fill-only`
   */
  readonly alignmentGuide: string;
  /**
   * grid and ruler lines.
   *
   * CSS: `--document-light-grid-line` · type `color` · usage `fill-only`
   */
  readonly gridLine: string;
  /**
   * CSS: `--document-light-comment-anchor` · type `color` · usage `fill-only`
   */
  readonly commentAnchor: string;
  /**
   * tagged `fill-only`: measured against the page it does not reach 4.5 : 1, so it is legal for
   * the change bar, the underline rule and the marker, and a tracked insertion's own glyphs
   * must stay `theme.*.text-primary`.
   *
   * CSS: `--document-light-tracked-change-insert` · type `color` · usage `fill-only` · 3.39 : 1
   * on `document.light.page`
   */
  readonly trackedChangeInsert: string;
  /**
   * tagged `fill-only` for the same reason as `tracked-change-insert`.
   *
   * CSS: `--document-light-tracked-change-delete` · type `color` · usage `fill-only` · 3.49 : 1
   * on `document.light.page`
   */
  readonly trackedChangeDelete: string;
}

